#!/usr/bin/env sh
# WG_POST_UP for the WireGuard server of gate.home — generated by kiwi-server.
# Runs inside the wg-easy container every time wg0 comes up.
# iptables-nft where the image has it: on an nf_tables host (Debian 13, Fedora) the
# legacy xtables calls fail inside the container with "Permission denied" on every
# table, the nft ones work — found on the first master (kiwi-server, problem 42)
if command -v iptables-nft >/dev/null 2>&1; then iptables() { command iptables-nft "$@"; }; fi
sleep 2

# MTU: clamp TCP MSS to the path MTU so WireGuard's overhead cannot stall connections
iptables -t mangle -A FORWARD -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu

# clients never reach the docker network behind the server
iptables -A FORWARD -s 10.8.0.0/16 -d 172.64.0.0/24 -j DROP

# group guests (10.8.1.0/24): reach nodes; other clients no; internet yes; admin pages no
# (before the wg0 accept-all below — iptables stops at the first match)
iptables -A FORWARD -s 10.8.1.0/24 -d 10.8.0.1 -j ACCEPT
iptables -A INPUT -i wg0 -s 10.8.1.0/24 -p tcp --dport 51821 -j DROP
iptables -A INPUT -i wg0 -s 10.8.1.0/24 -p tcp --dport 80 -j DROP
iptables -A INPUT -i wg0 -s 10.8.1.0/24 -p tcp --dport 443 -j DROP
iptables -A FORWARD -p icmp --icmp-type echo-request -s 10.8.1.0/24 -d 10.8.0.0/16 -j DROP
iptables -A FORWARD -p icmp --icmp-type echo-reply -s 10.8.1.0/24 -d 10.8.0.0/16 -j DROP
iptables -A FORWARD -s 10.8.1.0/24 -d 10.8.0.25 -j ACCEPT
iptables -A FORWARD -s 10.8.1.0/24 -d 10.8.0.6 -j ACCEPT
iptables -A FORWARD -s 10.8.1.0/24 -d 10.8.0.9 -j ACCEPT
iptables -A FORWARD -s 10.8.1.0/24 -d 10.8.0.0/16 -j DROP
iptables -t nat -A POSTROUTING -s 10.8.1.0/24 -o eth0 -j MASQUERADE

# group pentest (10.8.2.0/24): reach nothing; other clients no; internet yes; admin pages no
# (before the wg0 accept-all below — iptables stops at the first match)
iptables -A FORWARD -s 10.8.2.0/24 -d 10.8.0.1 -j ACCEPT
iptables -A INPUT -i wg0 -s 10.8.2.0/24 -p tcp --dport 51821 -j DROP
iptables -A INPUT -i wg0 -s 10.8.2.0/24 -p tcp --dport 80 -j DROP
iptables -A INPUT -i wg0 -s 10.8.2.0/24 -p tcp --dport 443 -j DROP
iptables -A FORWARD -p icmp --icmp-type echo-request -s 10.8.2.0/24 -d 10.8.0.0/16 -j DROP
iptables -A FORWARD -p icmp --icmp-type echo-reply -s 10.8.2.0/24 -d 10.8.0.0/16 -j DROP
iptables -A FORWARD -s 10.8.2.0/24 -d 10.8.0.0/16 -j DROP
iptables -t nat -A POSTROUTING -s 10.8.2.0/24 -o eth0 -j MASQUERADE

# group devices (10.8.3.0/24): reach all; other clients yes; internet yes; admin pages yes
# (before the wg0 accept-all below — iptables stops at the first match)
iptables -A FORWARD -s 10.8.3.0/24 -d 10.8.0.1 -j ACCEPT
iptables -t nat -A POSTROUTING -s 10.8.3.0/24 -o eth0 -j MASQUERADE

# group routers (10.8.4.0/24): reach all; other clients yes; internet yes; admin pages no
# (before the wg0 accept-all below — iptables stops at the first match)
iptables -A FORWARD -s 10.8.4.0/24 -d 10.8.0.1 -j ACCEPT
iptables -A INPUT -i wg0 -s 10.8.4.0/24 -p tcp --dport 51821 -j DROP
iptables -A INPUT -i wg0 -s 10.8.4.0/24 -p tcp --dport 80 -j DROP
iptables -A INPUT -i wg0 -s 10.8.4.0/24 -p tcp --dport 443 -j DROP
iptables -t nat -A POSTROUTING -s 10.8.4.0/24 -o eth0 -j MASQUERADE

# the admin pages for clients outside every group (the plain mesh, 10.8.0.0/24)

# stock wg-easy post-up
iptables -t nat -A POSTROUTING -s 10.8.0.0/24 -o eth0 -j MASQUERADE
iptables -A INPUT -p udp -m udp --dport 51820 -j ACCEPT
iptables -A INPUT -p tcp -m tcp --dport 80 -j ACCEPT
iptables -A FORWARD -i wg0 -j ACCEPT
iptables -A FORWARD -o wg0 -j ACCEPT
# the master itself and its containers reach the nodes as the server's mesh address
iptables -t nat -A POSTROUTING -s 172.64.0.0/24 -o wg0 -j MASQUERADE

# the double hop: everything leaves through the VPN client …
ip route del default
ip route add default via 172.64.0.2

# … except the server's own ports, which must answer on the real interface
grep -q novpn /etc/iproute2/rt_tables 2>/dev/null || echo "201 novpn" >> /etc/iproute2/rt_tables
ip rule add fwmark 65 table novpn
ip route add default via 172.64.0.1 dev eth0 table novpn
ip route flush cache
iptables -t mangle -A OUTPUT -p udp --sport 51820 -j MARK --set-mark 65
iptables -t mangle -A OUTPUT -p tcp --sport 51821 -j MARK --set-mark 65
iptables -t mangle -A OUTPUT -p tcp --sport 80 -j MARK --set-mark 65
